import sys

def can_form_palindrome(s):
    """
    Check if the string s can be rearranged into a palindrome with exactly k deletions.

    :param s: String to check for palindrome formation.
    :return: True if possible, False otherwise.
    """
    char_count = {}
    for c in s:
        char_count[c] = char_count.get(c, 0) + 1

    odd_counts = [count % 2 != 0 for count in char_count.values()]
    return len([count for count in odd_counts if count]) <= 1

def process_test_case():
