def find_max_subarray_sum(t):
    def max_subarray_sum(arr):
        current_sum = arr[0]
        global_max = arr[0]

        for i in range(1, len(arr)):
            if (i % 2 == 0 and arr[i] < 0) or (i % 2 != 0 and arr[i] > 0):
                current_sum += arr[i]
            else:
