def count_pairs(n, a):
    # Convert each power of 2 in a to its binary representation
    bin_a = [bin(x)[2:] for x in a]

    # Count the occurrences of each unique binary string
    counts = {}
    for s in bin_a:
        if s not in counts:
            counts[s] = 0
        counts[s] += 1

    # Calculate the number of valid pairs
    total_pairs = 0
    for i in range(len(bin_a)):
        for j in range(i + 1, len(bin_a)):
            if bin_a[i][::-1] == bin_a[j][::-1]:
                total_pairs += counts[bin_a[i]]

    return total_pairs

