def minExtraChar(s: str, dictionary: List[str]) -> int:
    # Create a set for quick lookup of dictionary words
    word_set = set(dictionary)

    def dp(i):
        # If i reaches the end of the string, no extra characters are needed
        if i == len(s):
            return 0

        # Initialize the result with the maximum possible value
        res = float('inf')

        # Try breaking the string at every position from i+1 to len(s)
        for j in range(i + 1, len(s) + 1):
            # Check if the substring s[i:j] is in the dictionary
            if s[i:j] in word_set:
                # Recursively calculate the cost of breaking the remaining part of the string
                res = min(res, dp(j))

        # Add the length of the current substring to the result
        return res + len(s[i:])

    # Start the dynamic programming calculation from the beginning of the string
    return dp(0)

def get_adjacent_same_color_count(n, queries):
    # Initialize the result list with zeros
    result = [0] * len(queries)

    for i, (index, color) in enumerate(queries):
        # Mark the current element as colored
        nums[index] = color

        # Count the number of adjacent elements with the same color
        for j in range(index - 1, index + 2):
            if 0 <= j < n:
                if nums[j] == color:
                    result[i] += 1

    return result

def minLengthAfterRemovals(s):
    # Initialize variables to keep track of the number of 'A's and 'C's remaining
    count_A = 0
    count_C = 0

    # Iterate through each character in the string
    for char in s:
        if char == 'A':
            count_A += 1
        elif char == 'C':
            count_C += 1

    # Calculate the minimum length by considering both cases
    return min(count_A + count_C, len(s))

def min_length(s):
    """
    Minimizes the length of the input string by repeatedly removing characters as described.

    :param s: A string consisting of lowercase English letters.
    :return: An integer representing the minimized length of the string.
    """
    def find_closest_left_right(char):
        for i in range(len(s)):
            if s[i] == char:
                return i - 1, i + 1

    while True:
        found_left, found_right = find_closest_left_right('a')
        if not found_left or not found_right:
            break

        # Remove the closest occurrences of 'a' to the left and right
        s = s[:found_left] + s[found_right+1:]

        # Find the next 'a' after the removed part
        found_next_a = None
        for i in range(found_left + 1, len(s)):
            if s[i] == 'a':
                found_next_a = i
                break

        if found_next_a is None:
            break

        # Remove the next 'a'
        s = s[:found_next_a]

    return len(s)

def count_beautiful_pairs(nums):
    """
    Counts the number of beautiful pairs in the given list of numbers.

    :param nums: List[int] - A list of non-negative integers less than 10000.
    :return: int - The total number of beautiful pairs.
    """
    def gcd(a, b):
        """Returns the greatest common divisor of two numbers."""
        while b:
            a, b = b, a % b
        return a

    result = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if gcd(int(str(nums[i])[0]), int(str(nums[j])[-1])) == 1:
                result += 1
    return result

