def maxNumberOfFamilies(self, words):
    """
    :type words: List[str]
    :rtype: int
    """
    # Count occurrences of each character in all words
    char_counts = {}
    for word in words:
        for char in word:
            if char not in char_counts:
                char_counts[char] = 0
            char_counts[char] += 1

    # Calculate the number of possible pairs based on character counts
    result = 0
    for count in char_counts.values():
        if count % 2 == 0:
            result += count // 2 * 2
        else:
            result += (count + 1) // 2 * 2

    return result

def countSpecialPerms(nums):
    MOD = 10**9 + 7

    def backtrack(index, prev):
        if index == len(nums):
            return 1

        result = 0
        for num in nums:
            if (prev % num == 0) ^ (num % prev == 0):
                result += backtrack(index + 1, num)

        return result % MOD

    return backtrack(0, 1)

