def maxJumps(nums, target):
    def dfs(index):
        if index >= len(nums) or abs(nums[index]) > target:
            return 0
        if dp[index]:
            return dp[index]

        res = 1
        for next_index in range(index + 1, min(len(nums), index + 1 + target)):
            if abs(nums[next_index] - nums[index]) > target:
                break
            res = max(res, 1 + dfs(next_index))

        dp[index] = res
        return res

    dp = [-1] * len(nums)
    return max(dfs(i) for i in range(len(nums)))

def min_changes_to_semi_palindrome(s, k):
    """
    Partition the string s into k substrings such that the sum of the number of letter changes required
    to turn each substring into a semi-palindrome is minimized.

    :param s: Input string consisting of lowercase English letters.
    :param k: Number of partitions.
    :return: Minimum number of letter changes required.
    """
    def is_semi_palindrome(substring):
        """Check if a substring is a semi-palindrome."""
        for i in range(len(substring) // 2):
            if substring[i] != substring[-(i + 1)]:
                return False
        return True

    def dfs(index, remaining_k, current_sum):
        """Depth-first search to find the minimum number of changes."""
        if index >= len(s) or remaining_k <= 0:
            return float('inf')

        # Try splitting the string at this index
        split_index = index
        while split_index < len(s) - 1 and s[split_index] == s[split_index + 1]:
            split_index += 1

        if split_index == len(s) - 1:
            if is_semi_palindrome(s[index:]):
                return 0
            else:
                return float('inf')

        if remaining_k > 0:
            # Option 1: Split at this index
            option_1 = 1 + dfs(split_index + 1, remaining_k - 1, current_sum)

            # Option 2: Keep the current part as is
            option_2 = dfs(index, remaining_k, current_sum)

            return min(option_1, option_2)

        # Option 3: Do nothing
        return current_sum

    return dfs(0, k, 0)

# Example usage
print(min_changes_to_semi_palindrome("abcac", 2))  # Output: 1
print(min_changes_to_semi_palindrome("abcdef", 2))  # Output: 2
