def split_strings(words, separator):
    # Split each word in the list using the provided separator
    return [word.split(separator) for word in words]

def count_ways(n: int, x: int) -> int:
    MOD = 10**9 + 7

    # Base case for recursion
    def helper(num, pow):
        if num == 0:
            return 1
        elif num < 0 or pow >= len(str(num)):
            return 0

        # Check if this combination has been computed before
        if (num, pow) not in memo:
            res = helper(num - pow**x, pow+1)
            res += helper(num, pow+1)
            res %= MOD
            memo[(num, pow)] = res

        return memo[(num, pow)]

    memo = {}
    return helper(n, 1)

def min_beautiful_substrings(s):
    def is_power_of_five(n):
        # Check if n is a power of five
        while n % 5 == 0:
            n //= 5
        return n == 1

    def find_min_partitions(start, end):
        if start > end:
            return float('inf')

        if start == end:
            return 1 if s[start] != '0' else float('inf')

        mid = (start + end) // 2
        left_count = find_min_partitions(start, mid)
        right_count = find_min_partitions(mid + 1, end)

        if left_count == float('inf') or right_count == float('inf'):
            return max(left_count, right_count)

        for i in range(start, mid + 1):
            if s[i] == '0':
                continue
            if is_power_of_five(int(s[i:end+1])):
                return left_count + 1

        return min(left_count, right_count)

    result = find_min_partitions(0, len(s))
    return result if result < float('inf') else -1

def findLongestValidSubstring(word: str, forbidden: List[str]) -> int:
    # Create a set for quick lookup of forbidden substrings
    forbidden_set = {s for s in forbidden}

    max_length = 0

    # Iterate through each character in the word to check for valid substrings
    for i in range(len(word)):
        current_length = 0
        for j in range(i, len(word)):
            current_substring = word[j - i + 1:j + 1]

            # Check if the current substring is not in the forbidden set
            if current_substring not in forbidden_set:
                current_length += 1
            else:
                break

        max_length = max(max_length, current_length)

    return max_length

def minValidSplit(nums):
    # Initialize variables for tracking the current dominant element and its frequency
    curr_dominant = None
    curr_freq = 0

    # Iterate through the array to find the first occurrence of the dominant element
    for num in nums:
        if num == curr_dominant:
            curr_freq += 1
        else:
            break

    # Check if all elements after the found dominant element are equal to the dominant element
    for num in nums[curr_freq:]:
        if num != curr_dominant:
            return -1

    # Calculate the total count of the dominant element
    total_count = len(nums) // (curr_freq << 1)

    # Find the minimum index of a valid split
    for i in range(len(nums)):
        if nums[:i+1].count(curr_dominant) * 2 > total_count:
            return i

