def maxScore(nums, x):
    """
    Calculate the maximum total score based on the given rules.

    :param nums: List[int] -- A list of integers representing the initial scores.
    :param x: int -- The penalty for moving between two numbers with different parities.
    :return: int -- The maximum total score achievable.
    """
    n = len(nums)
    dp = [[-float('inf')] * 2 for _ in range(n)]
    dp[0][nums[0] % 2] = nums[0]

    for i in range(1, n):
        for parity in range(2):
            if parity != (nums[i] % 2):
                continue
            for prev_parity in range(2):
                if prev_parity == (nums[i] % 2) or prev_parity == 0:
                    dp[i][parity] = max(dp[i][parity], dp[i-1][prev_parity] + nums[i])

    return max(dp[-1])

