def countSteppingNumbers(low: str, high: str) -> int:
    MOD = 10**9 + 7

    def dfs(num):
        if num > high or (num < low and len(str(num)) != len(str(low))):
            return 0

        if num >= low and num <= high:
            return 1

        res = 0
        for i in range(10):
            next_num = num * 10 + i
            if next_num == 0 or abs(next_num - num) == 1:
                res += dfs(next_num)

        return res % MOD

    return dfs(0)

def count_pairs_with_distance(coordinates, k):
    """
    Counts the number of pairs (i, j) such that i < j and the distance between points i and j is equal to k.

    :param coordinates: List[List[int]] - A list of [x, y] coordinates for each point.
    :param k: int - The target distance between any two points.
    :return: int - The number of valid pairs.
    """
    def calculate_distance(x1, y1, x2, y2):
        return abs(x1 ^ x2) + abs(y1 ^ y2)

    result = 0
    n = len(coordinates)
    for i in range(n):
        for j in range(i+1, n):
            if calculate_distance(*coordinates[i], *coordinates[j]) == k:
                result += 1

    return result

