def maxGold(n, offers):
    # Sort offers based on the starting point of each offer
    offers.sort(key=lambda x: x[0])

    dp = [0] * (n + 1)
    last_end = [-1] * (n + 1)

    for start, end, _ in offers:
        for i in range(end, start - 1, -1):
            if last_end[i] != -1:
                dp[i] = max(dp[i], dp[last_end[i]] + _)

        last_end[start] = end

    return max(dp)

