def countSymmetricIntegers(low: int, high: int) -> int:
    def is_symmetric(num):
        num_str = str(num)
        mid_index = len(num_str) // 2
        return num_str[:mid_index] == num_str[-mid_index:]

    count = 0
    for i in range(low, high + 1):
        if is_symmetric(i):
            count += 1

    return count

def count_beautiful_numbers(low: int, high: int, k: int) -> int:
    def has_equal_odd_even_digits(n):
        odd_count = sum(1 for d in str(n) if int(d) % 2 != 0)
        return odd_count == len(str(n)) - odd_count

    def is_divisible_by_k(n):
        return n % k == 0

    total_beautiful = 0
    for num in range(low, high + 1):
        if has_equal_odd_even_digits(num) and is_divisible_by_k(num):
            total_beautiful += 1
    return total_beautiful

def count_transformations(s, t, k):
    MOD = 10**9 + 7

    def dp(i, j, k):
        if i >= len(s) or j >= len(t):
            return 0
        if k == 0:
            return int(s[i:] == t[j:])

        res = 0
        for l in range(1, min(len(s) - i, len(t) - j)):
            res += (dp(i+l, j+l, k-1) * (len(s) - i)) % MOD

        return res

    return dp(0, 0, k)

def minCostToMakeStringsEqual(s1: str, s2: str, x: int) -> int:
    def flip(i):
        nonlocal s1, s2, x
        # Flip the ith bit in both strings
        s1 = s1[:i] + (str(int(not ord(s1[i]) & 1)))[::-1] + s1[i+1:]
        s2 = s2[:i] + (str(int(not ord(s2[i]) & 1)))[::-1] + s2[i+1:]

    def find_min_cost():
        global s1, s2, x
        dp = [[float('inf')] * len(s1) for _ in range(len(s1))]

        for i in range(len(s1)):
            if s1[i] != s2[i]:
                dp[i][i] = 0
            else:
                dp[i][i] = 1

        for l in range(2, len(s1)+1):
            for i in range(len(s1)-l+1):
                j = i+l-1
                for k in range(i, j):
                    if s1[k] != s2[k]:
                        continue
                    dp[i][j] = min(dp[i][j], dp[i][k]+dp[k+1][j])

        return dp[0][-1]

    flips_needed = find_min_cost()
    if flips_needed >= x:
        return -1

    # Perform the required flips
    while flips_needed > 0:
        flip(flips_needed)
        flips_needed -= 1

    return sum(ord(c) ^ ord(d) for c, d in zip(s1, s2))

def max_element_sum(nums):
    """
    Finds the maximum element-sum of a complete subset of indices in the given array.

    :param nums: List[int] - A list of positive integers.
    :return: int - The maximum element-sum of a complete subset.
    """
    # Sort the array to facilitate finding pairs with products close to squares
    nums.sort()
    left, right = 0, len(nums) - 1

    def check_complete_subset(subset_size):
        """Check if any subset of size 'subset_size' has all pairwise products as perfect squares."""
        for i in range(len(nums)):
            for j in range(i + 1, min(i + subset_size // 2 + 1, len(nums))):
                if (nums[i] * nums[j]) ** 0.5 % 1 != 0:
                    return False
        return True

    # Iterate over possible subset sizes starting from the largest
    for subset_size in range(len(nums), 0, -1):
        if check_complete_subset(subset_size):
            return sum(nums[:subset_size])
    return 0

