def min_length(nums):
    """
    Returns the minimum length of the array after performing operations as described.

    :param nums: List[int] - A sorted list of integers.
    :return: int - Minimum length achievable after performing operations.
    """
    left, right = 0, len(nums) - 1

    while left < right:
        if nums[left] < nums[right]:
            return len(nums) - (right - left)
        else:
            left += 1

    return 0

