def longestSubsequence(nums, target):
    dp = [-1] * (target + 1)
    dp[0] = 0

    for num in nums:
        new_dp = [dp[num]] + [max(dp[j - num] if j >= num else -1) for j in range(target + 1)]
        dp = new_dp

    return max(dp)

def find_smallest_beautiful_substring(s: str, k: int) -> str:
    def count_ones(sub: str) -> int:
        """Count the number of '1's in the substring."""
        return sub.count('1')

    min_length = float('inf')
    result = ""

    for start in range(len(s)):
        for end in range(start + 1, len(s) + 1):
            substring = s[start:end]
            if count_ones(substring) == k:
                if len(substring) < min_length or (len(substring) == min_length and substring < result):
                    min_length = len(substring)
                    result = substring

    return result

def last_visited_integer(words):
    # Initialize variables to keep track of the count of consecutive "prev"s and the last visited integer
    prev_count = 0
    last_visited = -1

    # Iterate through each word in the list
    for i, word in enumerate(words):
        if word == "prev":
            # Increment the count of consecutive "prev"s
            prev_count += 1

            # If the count exceeds the total number of visited integers, set the last visited to -1
            if prev_count > len(words) // 2:
                last_visited = -1
            else:
                # Otherwise, update the last visited with the corresponding value from the reversed list
                last_visited = words[len(words) - prev_count][::-1][len(words) // 2 - 1]

    return [last_visited] * len(words)

def canMakePalindrome(s, queries):
    def is_palindrome(substring):
        return substring == substring[::-1]

    for q in queries:
        # Rearrange substrings as per the query
        s[q[0]:q[1]] = sorted(s[q[0]:q[1]])
        s[q[2]:q[3]] = sorted(s[q[2]:q[3]])

        # Check if the entire string becomes a palindrome after rearrangement
        if is_palindrome(s[:len(s)//2]) and is_palindrome(s[len(s)//2:]):
            return True

    return False

def min_operations_to_equal(s1, s2, s3):
    """
    Returns the minimum number of operations needed to make three strings equal or -1 if it's impossible.

    :param s1: First string
    :param s2: Second string
    :param s3: Third string
    :return: Minimum number of operations required or -1 if it's impossible
    """
    def count_operations(str1, str2, str3):
        """Helper function to count operations for two strings."""
        i, j, k = len(str1) - 1, len(str2) - 1, len(str3) - 1

        while i >= 0:
            if str1[i] != str2[j]:
                break
            i -= 1
            j -= 1

        while j >= 0:
            if str2[j] != str3[k]:
                break
            j -= 1
            k -= 1

        # If all characters match up to the end of both strings, we can compare the remaining parts
        if i == -1 and j == -1:
            return max(len(str1), len(str2), len(str3)) // 2

        # Otherwise, we cannot make the strings equal
        return -1

    # Check each pair of strings
    result = count_operations(s1, s2, s3)
    if result != -1:
        return result + count_operations(s1, s2, s3)

    result = count_operations(s1, s3, s2)
    if result != -1:
        return result + count_operations(s1, s3, s2)

    result = count_operations(s2, s1, s3)
    if result != -1:
        return result + count_operations(s2, s1, s3)

    result = count_operations(s2, s3, s1)
    if result != -1:
        return result + count_operations(s2, s3, s1)

    result = count_operations(s3, s1, s2)
    if result != -1:
        return result + count_operations(s3, s1, s2)

    result = count_operations(s3, s2, s1)
    if result != -1:
        return result + count_operations(s3, s2, s1)

    return -1

