def countSubarrays(nums, k):
    max_num = max(nums)
    left = right = 0
    count = 0

    while right < len(nums):
        if nums[right] == max_num:
            count += 1

        while count >= k:
            if nums[left] == max_num:
                count -= 1
            left += 1

        right += 1

    return right - left

def count_complete_substrings(word, k):
    def is_valid(substring):
        char_count = [0] * 26
        last_char_index = -1
        for i, char in enumerate(substring):
            index = ord(char) - ord('a')
            if char_count[index] == k:
                return False
            if abs(index - last_char_index) > 2:
                return False
            char_count[index] += 1
            last_char_index = index
        return True

    total_count = 0
    n = len(word)
    for i in range(n):
        for j in range(i + k, min(i + 2 * k, n)):
            if is_valid(word[i:j]):
                total_count += 1
    return total_count

def countInfectionSequences(n: int, sick: List[int]) -> int:
    MOD = 10**9 + 7

    # Initialize DP table where dp[i][j] represents the number of ways to infect j children up to index i
    dp = [[0 for _ in range(n+1)] for _ in range(n)]

    # Base case: no children infected initially
    dp[0][0] = 1

    # Fill the DP table
    for i in range(1, n):
        for j in range(i+1):
            if j == 0 or j == i:
                dp[i][j] = (dp[i-1][j-1] + dp[i-1][j]) % MOD
            else:
                dp[i][j] = (dp[i-1][j-1] * 2) % MOD

    # Calculate the total number of infection sequences
    result = sum(dp[n-1]) % MOD
    return result

def max_partitions(s: str, k: int) -> int:
    def dfs(index):
        if index == len(s):
            return 0

        # Try changing each character to see if it improves the result
        for i in range(97, 123):  # ASCII values for A-Z
            new_s = list(s)
            new_s[index] = chr(i)
            count = collections.Counter(new_s[:index]) + collections.Counter(new_s[index+1:])

            if len(count) > k:
                continue

            partitions = dfs(index + 1)
            if partitions != -1:
                partitions += 1
                break
        else:
            partitions = -1

        return partitions

    return dfs(0)

