def minArrayLength(nums):
    """
    Minimizes the length of the input list by repeatedly selecting two distinct indices,
    computing their modulo, inserting the result at the end, and deleting them.

    :param nums: List[int] - A list of positive integers.
    :return: int - The minimized length of the list.
    """
    while True:
        for i in range(len(nums) - 1):
            if nums[i] > 0 and nums[i + 1] > 0:
                nums.append((nums[i] % nums[i + 1]) % 10)
                del nums[i + 1:i + 2]
                break
        else:
            return len(nums)

