def countMatchingSubarrays(nums, pattern):
    """
    Counts the number of subarrays in nums that match the given pattern.

    :param nums: List[int] -- A list of integers representing the input array.
    :param pattern: List[int] -- A list of integers (1, 0, -1) representing the pattern.
    :return: int -- The count of matching subarrays.
    """
    def matches(pattern, subarr):
        for i in range(len(subarr)):
            if pattern[i] == 1:
                if subarr[i] >= subarr[i+1]:
                    return False
            elif pattern[i] == -1:
                if subarr[i] <= subarr[i+1]:
                    return False
            else:
                if subarr[i] != subarr[i+1]:
                    return False
        return True

    count = 0
    for start in range(len(nums) - len(pattern) + 1):
        subarr = nums[start:start+len(pattern)]
        if matches(pattern, subarr):
            count += 1
    return count

def canSortArray(nums):
    """
    :type nums: List[int]
    :rtype: bool
    """
    def countSetBits(n):
        """Count the number of set bits in n."""
        return bin(n).count('1')

    for i in range(len(nums) - 1):
        if countSetBits(nums[i]) != countSetBits(nums[i + 1]):
            # Check if swapping these elements would make them equal
            if countSetBits(nums[i]) == countSetBits(nums[i + 1]):
                nums[i], nums[i + 1] = nums[i + 1], nums[i]
                continue
            # If not, check if the current pair can be swapped to match another pair
            for j in range(i + 1, len(nums)):
                if countSetBits(nums[j]) == countSetBits(nums[i]):
                    nums[i], nums[j] = nums[j], nums[i]
                    break
            else:
                return False
    return True

def max_palindromes(words):
    """
    Returns the maximum number of palindromic substrings that can be formed by swapping characters between two different indices.

    :param words: List[str] - A list of strings where each string contains only lowercase English letters.
    :return: int - The maximum number of palindromic substrings that can be formed.
    """
    def is_palindrome(s):
        return s == s[::-1]

    # Count occurrences of each character
    char_count = {}
    for word in words:
        for char in word:
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1

    # Sort words based on their lengths
    words.sort(key=len)

    total_length = sum(len(word) for word in words)
    odd_chars = [char for char, count in char_count.items() if count % 2 != 0]

    # If all characters have even counts or there's exactly one odd-count character, all words can form palindromes
    if len(odd_chars) == 0 or len(odd_chars) == 1:
        return total_length // 2 + 1

    # Calculate the minimum number of swaps needed to make all words palindromic
    min_swaps_needed = 0
    for word in words:
        half_len = len(word) // 2
        for i in range(half_len):
            if word[i] != word[-i-1]:
                min_swaps_needed += 1

    # Each swap reduces the number of non-palindromic substrings by 2
    return total_length - 2 * min_swaps_needed

