def find_winner(N, S):
    # Count occurrences of 'T' (Takahashi's win) and 'A' (Aoki's win)
    takahashi_wins = S.count('T')
    aoki_wins = S.count('A')

    # Determine the overall winner based on the counts
    if takahashi_wins > aoki_wins:
        return "T"
    elif aoki_wins > takahashi_wins:
        return "A"
    else:
        # If both have the same count, check which came first
        for i in range(1, N + 1):
            if S[:i].count('T') > S[:i].count('A'):
                return "T" if i <= N // 2 else "A"
            elif S[:i].count('T') < S[:i].count('A'):
                return "A" if i <= N // 2 else "T"

