# Define constants for modular exponentiation
MOD = 998244353
P = 31  # Prime used for modular arithmetic

def mod_exp(base, exp):
    """Modular exponentiation using repeated squaring."""
    result = 1
    base %= MOD
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % MOD
        base = (base * base) % MOD
        exp //= 2
    return result

def ddostype_string(s):
    """
    Check if a string s is a DDoS-type string.

    A DDoS-type string has its first, second, and fourth characters as uppercase,
    and the third character as a lowercase letter.
    """
    return s[0].isupper() and s[1] == s[2] and s[3].islower()

def count_non_ddostransformed_strings(s):
    """
    Count the number of non-DDoS-type transformed strings where '?' is replaced by any char.
    """
    n = len(s)
    dp = [[0] * P for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(P):
            if s[i - 1] != '?':
                dp[i][(j << 1) | int(s[i - 1].islower())] += dp[i - 1][j]
                dp[i][(j << 1) | int(not s[i - 1].isupper())] += dp[i - 1][j]
            else:
                for k in range(P):
                    dp[i][(k << 1)] += dp[i - 1][k]
                    dp[i][(k << 1) | int(k < j)] += dp[i - 1][k]

    return sum(dp[n]) % MOD

