def check_strings(N, M, *strings):
    # Check if any two strings differ by more than one character
    for i in range(N - 1):
        if sum(1 for j in range(M) if strings[i][j] != strings[i + 1][j]) > 1:
            return "No"

    # Check if we can rearrange the strings to form a valid sequence
    for perm in permutations(strings):
        valid = True
        for i in range(N - 1):
            diff_count = sum(1 for j in range(M) if perm[i][j] != perm[i + 1][j])
            if diff_count > 1:
                valid = False
                break
        if valid:
            return "Yes"

    return "No"

