def process_queries(N, Q):
    # Initialize adjacency list for graph representation
    adj_list = [[] for _ in range(N)]

    def add_edge(u, v):
        if u != v:
            adj_list[u].append(v)
            adj_list[v].append(u)

    def remove_edges(vertex):
        if vertex < N:
            adj_list[vertex] = []
        else:
            del adj_list[vertex]

    def count_unconnected_vertices():
        unconnected_count = 0
        for i in range(1, N + 1):
            if len(adj_list[i]) == 0:
                unconnected_count += 1
        return unconnected_count

    for _ in range(Q):
        query_type, *args = map(int, input().split())

        if query_type == 1:
            u, v = args
            add_edge(u, v)
        elif query_type == 2:
            v = args[0]
            remove_edges(v)
        else:
            raise ValueError("Invalid query type")

        print(count_unconnected_vertices())

