def count_bad_mood_pairs(N, M, photos):
    # Initialize a list to keep track of which people have been seen before
    seen = [False] * (N + 1)

    # Count the number of unique pairs of people who have been seen together
    total_pairs = 0

    for photo in range(M):
        for i in range(N):
            if not seen[photos[photo][i]]:
                seen[photos[photo][i]] = True

                # Check if the current person has already been paired with someone else
                if seen[photos[photo][(i - 1) % N]]:
                    total_pairs += 1

                # Check if the current person has not been paired with anyone yet
                if not seen[photos[photo][(i + 1) % N]]:
                    total_pairs += 1

