import sys

def calculate_ways(S):
    MOD = 998244353

    def dp(i, j, k):
        if i == len(S):
            return 1 if j == k else 0

        res = 0
        if S[i] != '?':
            res += dp(i + 1, j, k)

        if S[i] == '?' and j < k:
            res += dp(i + 1, j + 1, k - 1)

        if S[i] == '?' and j > k:
            res += dp(i + 1, j - 1, k + 1)

        return res % MOD

    return dp(0, 0, 0)

