def find_strongest_programmer(N, M, superiority_relations):
    """
    Determines the strongest programmer based on the given superiority relations.

    :param N: Number of programmers
    :param M: Number of superiority relations
    :param superiority_relations: List of tuples representing superiority relations
    :return: The number of the strongest programmer or -1 if not unique
    """
    # Initialize adjacency list for graph representation
    graph = {i: [] for i in range(1, N+1)}
    for x, y in superiority_relations:
        graph[x].append(y)
        graph[y].append(x)

    def dfs(programmer, visited):
        if visited[programmer]:
            return False
        visited[programmer] = True
        for neighbor in graph[programmer]:
            if not dfs(neighbor, visited):
                return False
        return True

    # Check each programmer to see if they are the strongest
    for programmer in range(1, N+1):
        if not dfs(programmer, [False]*N):
            return -1

    return programmer

