def min_cost_to_earn_points(n, m, data):
    dp = [[float('inf')] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        c, p, s = data[i - 1]

        for j in range(m + 1):
            if j >= s[-1]:
                dp[i][j] = min(dp[i][j], dp[i - 1][j])

            for k in range(p):
                if j + s[k] <= m:
                    dp[i][j + s[k]] = min(dp[i][j + s[k]], dp[i - 1][j] + c)

    return dp[n][m]

