import math

def check_integer(N):
    # Calculate the prime factors of N
    factors = []
    while N % 2 == 0:
        factors.append(2)
        N //= 2
    for i in range(3, int(math.sqrt(N)) + 1, 2):
        while N % i == 0:
            factors.append(i)
            N //= i
    if N > 2:
        factors.append(N)

    # Check if any two distinct factors can be powers of 2 and 3 respectively
    for factor in set(factors):
        if len([i for i in factors if i != factor and (factor ** 2) // i == factor]) >= 2:
            return "Yes"

    return "No"

