def min_travel_time(N, A, B, C, distances):
    dp = [[float('inf')] * (N+1) for _ in range(N+1)]

    # Initialize the starting point
    dp[1][1] = 0

    for k in range(1, N):
        for i in range(1, N+1):
            for j in range(i+1, N+1):
                if dp[i][k] != float('inf') and dp[j][k] != float('inf'):
                    cost_car = dp[i][k] + distances[i][j] * A
                    cost_train = dp[i][k] + distances[i][j] * B + C
                    dp[j][k] = min(dp[j][k], cost_car, cost_train)

    return dp[N][N]

