def min_cost(N, lengths, Ls, Cs, Ks):
    dp = [[float('inf')] * (Ks + 1) for _ in range(1 << N)]

    # Initialize base cases
    for k in range(Ks + 1):
        dp[1][k] = sum(Cs[i] * max(Ls[i], lengths[j]) for i in range(N) for j in range(k))

    for mask in range(1, 1 << N):
        for k in range(Ks + 1):
            if mask & (1 << (i := next((j for j in range(N) if (mask >> j) & 1), None))) == 0:
                continue

            for l in range(mask | (1 << i)):
                dp[mask | (1 << i)][k] = min(dp[mask | (1 << i)][k], 
                                             dp[l][k - 1] + sum(Cs[i] * max(Ls[i], lengths[j]) for j in range(l.bit_count()) if (l >> j) & 1))

    return -1 if dp[-1][-1] >= float('inf') else dp[-1][-1]

