            continue
        else:
            break

    j = i + 1
    while j < min(i + m, n) and x[j] == '#':
        j += 1

    if j >= n - m or (j < n - m and x[j] != t[i]):
        return "No"

    k = j
    while k < n and x[k] == '#':
