def min_operations_to_match(A, B):
    def swap_rows(grid, i, j):
        grid[i], grid[j] = grid[j], grid[i]

    def swap_columns(grid, i, j):
        for row in range(len(grid)):
            grid[row][i], grid[row][j] = grid[row][j], grid[row][i]

    # Check if grid A matches grid B
    if sorted(A) == sorted(B):
        return 0

    # Try to match grid A to grid B using swaps
    for _ in range(10):  # Arbitrarily large number of iterations
        swapped = False
        for i in range(1, len(A)):
            if A[i-1] > A[i]:
                swap_rows(A, i-1, i)
                swapped = True
            elif A[i-1] < A[i]:
                swap_rows(A, i-1, i)
                swapped = True

        for j in range(1, len(A[0])):
            if A[0][j-1] > A[0][j]:
                swap_columns(A, 0, j)
                swapped = True
            elif A[0][j-1] < A[0][j]:
                swap_columns(A, 0, j)
                swapped = True

        if not swapped:
            break

    # Count the number of swaps made
    count = sum(1 for i in range(1, len(A)) for j in range(1, len(A[0])) if A[i-1][j-1] != B[i-1][j-1])
    return count

