import sys
from heapq import heappush, heappop

def dijkstra(graph, start):
    # Initialize distances and visited set
    distances = {vertex: float('inf') for vertex in range(1, n + 1)}
    distances[start] = 0
    visited = set()

    # Priority queue for nodes to process
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_vertex = heappop(priority_queue)

        if current_vertex in visited:
            continue

        visited.add(current_vertex)

        for neighbor, weight in graph[current_vertex]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(priority_queue, (distance, neighbor))

    return distances

def find_hamiltonian_path(graph, start, end):
    distances = dijkstra(graph, start)

    # Check if there's a path from start to end
    if distances[end] == float('inf'):
        return None

    # Find the next vertex to visit
    next_vertex = end
    while True:
        neighbors = graph[next_vertex]
        for neighbor, _ in neighbors:
            if distances[neighbor] == distances[next_vertex] - 1:
                next_vertex = neighbor
                break
        else:
            return None

    # Reconstruct the path
    path = [end]
    while path[-1] != start:
        for neighbor, _ in graph[path[-1]]:
            if distances[neighbor] == distances[path[-1]] - 1:
                path.append(neighbor)
                break
    path.reverse()

    return path

