def min_passengers(N, A):
    """
    Calculate the minimum possible current number of passengers on the bus.

    Parameters:
    N (int): Number of stops.
    A (list[int]): List of changes in passenger count at each stop.

    Returns:
    int: Minimum possible current number of passengers.
    """
    total_change = sum(A)
    if total_change > 0:
        return max(0, total_change // 2)
    elif total_change < 0:
        return min(0, total_change // 2)
    else:
        return 0

