def min_moves_to_same_cell(N, S):
    """
    Finds the minimum number of moves required to bring two players to the same cell,
    or prints -1 if it's impossible.

    :param N: Integer representing the size of the grid.
    :param S: List of strings, each string represents a row of the grid.
    :return: Minimum number of moves or -1 if impossible.
    """
    def can_move(i, j, di, dj):
        return 0 <= i + di < N and 0 <= j + dj < N and S[i][j] == '.' and S[i + di][j + dj] == '.'

    def bfs(start_x, start_y, end_x, end_y):
        queue = [(start_x, start_y)]
        visited = set([(start_x, start_y)])

        while queue:
            x, y = queue.pop(0)

            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy

                if can_move(nx, ny, dx, dy) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))

                    if (nx, ny) == (end_x, end_y):
                        return len(queue) - 1

        return -1

    for i in range(N):
        for j in range(N):
            if S[i][j] == 'P':
                start_x, start_y = i, j
                break

    for i in range(N):
        for j in range(N):
            if S[i][j] == 'P':
                end_x, end_y = i, j
                break

    result = bfs(start_x, start_y, end_x, end_y)

    return result if result != -1 else -1

