    import sys

    def read_input():
        return [line.strip() for line in sys.stdin]

    def parse_input(lines):
        h, w = map(int, lines[0].split())
        grid = []
        for i in range(1, h + 1):
            grid.append(list(line))
        n = int(lines[h + 1])
        r_c_e = [(int(r), int(c), int(e)) for r, c, e in zip(*[iter(lines[h + 2])] * 3)]
        return h, w, grid, n, r_c_e

    def find_start_and_end(grid):
        for i, row in enumerate(grid):
            for j, cell in enumerate(row):
                if cell == 'S':
                    start_row, start_col = i, j
                elif cell == 'T':
                    end_row, end_col = i, j
        return start_row, start_col, end_row, end_col

    def check_medicine_effect(medicines, target_energy):
        for medicine in medicines:
            if medicine[2] <= target_energy:
                return True
        return False

    def calculate_energy_consumption(start_row, start_col, end_row, end_col, medicines):
        total_energy = sum(medicine[2] for medicine in medicines)
        distance = abs(end_row - start_row) + abs(end_col - start_col)
        return min(total_energy, distance)

    def main():
        h, w, grid, n, medicines = parse_input(read_input())
        start_row, start_col, end_row, end_col = find_start_and_end(grid)

        if start_row == end_row and start_col == end_col:
            return "Yes"

        medicines.sort(key=lambda x: x[2], reverse=True)

        while medicines:
            medicine = medicines.pop()
            if check_medicine_effect(medicines, medicine[2]):
                continue

            new_energy = calculate_energy_consumption(start_row, start_col, end_row, end_col, medicines)

            if new_energy >= medicine[2]:
                medicines.remove((start_row, start_col, medicine[2]))

                if start_row == end_row and start_col == end_col:
                    return "Yes"

                if start_row > end_row:
                    medicines.append((end_row, end_col, medicine[2]))
                else:
                    medicines.append((start_row, start_col, medicine[2]))

                break

        return "No"

    print(main())

