import sys

def min_f_value(N, edges, C):
    # Implementing Prim's algorithm to find the minimum spanning tree
    parent = [None] * (N+1)
    rank = [0] * (N+1)

    def find(x):
        if parent[x] == None:
            return x
        else:
            parent[x] = find(parent[x])
            return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    for u, v in edges:
        union(u, v)

    # Calculate the sum of products of each vertex and its distance to all other vertices
    total_sum = 0
    for i in range(1, N+1):
        total_sum += C[i-1] * len([j for j in range(1, N+1) if find(i) != find(j)])

    return total_sum

