def perform_operations(N, M):
    # Initialize adjacency list for friendship graph
    adj_list = [[] for _ in range(N)]

    # Build the friendship graph
    for i in range(M):
        u, v = map(int, input().split())
        adj_list[u - 1].append(v - 1)
        adj_list[v - 1].append(u - 1)

    # Function to find the size of the largest independent set
    def max_independent_set():
        dp = [0] * N
        for node in range(N):
            for neighbor in adj_list[node]:
                dp[neighbor] = max(dp[neighbor], dp[node])
            dp[node] += 1
        return max(dp)

    # Calculate the maximum number of operations
    return max_independent_set() ** 2

