def calculate_distance_sum(N, points):
    # Initialize distances array with infinity for all pairs except self-distance which is zero
    dists = [[float('inf')] * N for _ in range(N)]

    # Calculate pairwise distances using Floyd-Warshall algorithm
    for k in range(N):
        for i in range(N):
            for j in range(N):
                if dists[i][k] + dists[k][j] < dists[i][j]:
                    dists[i][j] = dists[i][k] + dists[k][j]

    # Sum up the distances for each pair (i, j) where i < j
    return sum(dists[i][j] for i in range(1, N) for j in range(i + 1, N))

