def build_graph(n, edges):
    graph = defaultdict(list)
    for k, c, vertices in edges:
        for u, v in zip(vertices[:-1], vertices[1:]):
            graph[u].append((v, c))
            graph[v].append((u, c))
    return graph

def dfs(graph, start, visited):
    if len(visited) == len(graph):
        return True
    stack = [start]
    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            for neighbor, weight in graph[node]:
                if neighbor not in visited:
                    stack.append(neighbor)
    return False

def check_connectivity(graph):
    visited = set([1])
    for vertex in graph:
        if vertex != 1 and dfs(graph, vertex, visited):
            return False
    return True

def find_min_spanning_tree_weight(graph):
    def prim_mst(graph):
        min_cost = 0
        visited = {1}
        priority_queue = [(0, 1)]
        while priority_queue:
            cost, node = heapq.heappop(priority_queue)
            if node not in visited:
                visited.add(node)
                min_cost += cost
                for neighbor, weight in graph[node]:
                    if neighbor not in visited:
                        heapq.heappush(priority_queue, (weight, neighbor))
        return min_cost

    return prim_mst(graph)

