def optimal_game_winner(N):
    """
    Determines the winner of the game between Takahashi and Aoki based on the rules provided.

    Parameters:
    N (int): Number of cards.

    Returns:
    str: "Takahashi" if Takahashi wins, "Aoki" otherwise.
    """
    # Since we need to simulate the game for each possible initial configuration,
    # this approach is not feasible due to the large number of configurations.
    # Instead, we will use dynamic programming to solve the problem efficiently.
    dp = [[False] * 2 for _ in range(1 << N)]
    mod = 10**9 + 7

    def dfs(mask):
        if mask == 0:
            return True
        if dp[mask][0]:
            return False

        for i in range(N):
            for j in range(i+1, N):
                if (mask & (1 << i)) and (mask & (1 << j)):
                    continue

                if (i % 2 == 0 and j % 2 != 0) or (i % 2 != 0 and j % 2 == 0):
                    if dfs((mask | (1 << i)) | (1 << j)):
                        dp[mask][0] = True
                        break
                else:
                    if dfs((mask | (1 << i)) & ~(1 << j)):
                        dp[mask][0] = True
                        break
        return dp[mask][0]

    return 'Takahashi' if dfs((1 << N) - 1) else 'Aoki'

