def findShortestSubstrings(arr):
    """
    Finds the shortest unique substring for each string in the input list `arr`.

    Parameters:
    arr (List[str]): A list of non-empty strings.

    Returns:
    List[str]: A list where each element represents the shortest unique substring of the corresponding string in `arr`.
    """
    # Dictionary to store the frequency and first occurrence index of each character in all strings
    char_freqs = {}
    for i, s in enumerate(arr):
        freqs = {}
        for j, c in enumerate(s):
            if c in freqs:
                freqs[c][1] += 1
            else:
                freqs[c] = [j, 1]
        char_freqs[i] = freqs

    # Dictionary to store the minimum length of unique substrings found so far
    min_len_dict = {i: float('inf') for i in range(len(arr))}

    def dfs(i, current_str, current_min_len):
        if i >= len(arr) or current_min_len > min_len_dict[i]:
            return

        # Check if this combination has been seen before
        if (current_str, tuple(min_len_dict.values())) in visited:
            return

        visited.add((current_str, tuple(min_len_dict.values())))

        # Update the minimum length of unique substrings found so far
        min_len_dict[i] = min(min_len_dict[i], len(current_str))

        # Try removing characters one by one until the substring becomes invalid
        for j in range(1, len(current_str)):
            new_str = current_str[:j]
            if new_str in char_freqs[i]:
                removed_char = current_str[j - 1]
                remaining_freqs = char_freqs[i][removed_char][1:]

                # Remove the character from its frequency dictionary
                if remaining_freqs[0] == 1:
                    del char_freqs[i][removed_char]
                else:
                    char_freqs[i][removed_char][1] -= 1

                # Recursively check the next substring
                dfs(i + 1, new_str, min_len_dict[i])

                # Re-add the character back to its frequency dictionary
                if remaining_freqs[0] == 1:
                    char_freqs[i][removed_char] = [j, 1]
                else:
                    char_freqs[i][removed_char][1] += 1

            # If the substring is valid, update the result with the current minimum length
            if current_min_len != float('inf'):
                if len(new_str) < current_min_len:
                    current_min_len = len(new_str)
                    result[i] = new_str

    result = [[] for _ in range(len(arr))]
    visited = set()
    for i in range(len(arr)):
        dfs(i, "", float('inf'))

    return result

def maxStrength(nums, k):
    """
    :type nums: List[int]
    :type k: int
    :rtype: int
    """
    # Initialize prefix sums
    prefix_sums = [0]
    for num in nums:
        prefix_sums.append(prefix_sums[-1] + num)

    # Calculate the number of valid subarrays for each starting index
    dp = [[0] * len(nums) for _ in range(k)]
    for start in range(len(nums)):
        if start % 2 == 0:
            dp[start][start] = prefix_sums[start + 1] - prefix_sums[start]
        else:
            dp[start][start] = prefix_sums[start + 1] - prefix_sums[start]

    # Fill the DP table
    for length in range(2, k + 1):
        for start in range(len(nums) - length + 1):
            end = start + length - 1
            if start % 2 == 0:
                dp[start][end] = max(dp[start + 1][end] + (prefix_sums[end + 1] - prefix_sums[start]), dp[start][end - 1])
            else:
                dp[start][end] = max(dp[start + 1][end] + (prefix_sums[end + 1] - prefix_sums[start]), dp[start][end - 1])

    return dp[0][-1]

def count_substrings(s, c):
    """
    Returns the total number of substrings of s that start and end with c.

    :param s: Input string consisting of lowercase English letters.
    :param c: Character to check for as the start and end of substrings.
    :return: Total number of substrings starting and ending with c.
    """
    count = 0
    left = -1
    right = -1

    for i in range(len(s)):
        if s[i] == c:
            if left == -1:
                left = i
            else:
                right = i
                break

    if left != -1:
        while left >= 0:
            count += (right + 1) * (left + 1)
            left -= 1
            right -= 1

    return count

