from typing import List

def is_prime(n: int) -> bool:
    """Check if a number is prime."""
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def max_distance(nums: List[int]) -> int:
    """
    Finds the maximum distance between the indices of two prime numbers in the list.

    Args:
    nums: A list of integers.

    Returns:
    The maximum distance between the indices of two prime numbers.
    """
    primes = []
    for i, num in enumerate(nums):
        if is_prime(num):
            primes.append(i)

    max_dist = 0
    for i in range(len(primes)):
        for j in range(i + 1, len(primes)):
            dist = abs(primes[j] - primes[i])
            max_dist = max(max_dist, dist)

    return max_dist

def kthSmallestAmount(coins, k):
    # Sort the coins in ascending order
    sorted_coins = sorted(coins)

    # Initialize variables for binary search
    left, right = 0, sum(sorted_coins) + 1

    while left < right:
        mid = (left + right) // 2
        count = 0

        # Count how many numbers less than or equal to mid can be formed with the coins
        for coin in sorted_coins:
            if mid % coin == 0:
                count += mid // coin - 1
            else:
                count += mid // coin

        # Adjust the search range based on the count
        if count >= k:
            right = mid
        else:
            left = mid + 1

    return left

def minimize_string(s):
    """
    Replaces all occurrences of '?' in the input string s with any lowercase English letter
    such that the value of the resulting string is minimized. Returns the lexicographically
    smallest string among all possible minimizations.
    """
    n = len(s)
    dp = [[float('inf')] * 26 for _ in range(n)]

    # Initialize DP table
    for i in range(n):
        if s[i] != '?':
            dp[i][ord(s[i]) - ord('a')] = 0

    # Fill DP table
    for i in range(n-1, -1, -1):
        if s[i] == '?':
            for j in range(26):
                dp[i][j] = min(dp[i+1][k] + (1 if k == j else 0) for k in range(26))

    # Find the lexicographically smallest result
    res = ''
    for i in range(n):
        if s[i] == '?':
            for j in range(26):
                if dp[i][j] < dp[i+1][j]:
                    res += chr(j + ord('a'))
                    break
            else:
                res += 'a'
        else:
            res += s[i]

    return res

