def countSubsequencesWithSum(nums, k):
    MOD = 10**9 + 7
    dp = [[0 for _ in range(k+1)] for _ in range(len(nums)+1)]

    # Initialize base case
    for i in range(1, len(nums) + 1):
        dp[i][0] = 1

    # Fill the DP table
    for i in range(1, len(nums) + 1):
        for j in range(1, k + 1):
            if nums[i-1] > j:
                dp[i][j] = dp[i-1][j]
            else:
                dp[i][j] = (dp[i-1][j] + dp[i-1][j - nums[i-1]]) % MOD

    # Calculate the total power
    total_power = sum(dp[len(nums)][i] for i in range(1, k + 1)) % MOD

    return total_power

