def sumOfPowers(nums, k):
    MOD = 10**9 + 7
    dp = [[0 for _ in range(k+1)] for _ in range(len(nums)+1)]

    # Initialize base case
    for i in range(1, len(nums) + 1):
        dp[i][1] = abs(nums[0] - nums[i-1])

    # Fill DP table
    for j in range(2, k+1):
        for i in range(j, len(nums) + 1):
            min_diff = float('inf')
            for m in range(i-j+1, i+1):
                diff = abs(nums[m-1] - nums[i-1])
                if diff < min_diff:
                    min_diff = diff
            dp[i][j] = (dp[i][j-1] + min_diff) % MOD

    return dp[-1][-1]

