def findMedianOfUniquenessArray(nums):
    # Calculate the uniqueness array
    def calculate_uniqueness_array():
        n = len(nums)
        if n == 0:
            return []

        unique_count = [1] * n
        for i in range(1, n):
            if nums[i] != nums[i-1]:
                unique_count[i] = unique_count[i-1] + 1

        return unique_count

    # Find the median of the uniqueness array
    def find_median(unique_count):
        mid_index = (len(unique_count) - 1) // 2
        if len(unique_count) % 2 == 0:
            return min(unique_count[mid_index], unique_count[mid_index+1])
        else:
            return unique_count[mid_index]

    # Main logic
    uniqueness_array = calculate_uniqueness_array()
    return find_median(uniqueness_array)

