def count_right_triangles(grid):
    """
    Counts the number of right triangles in a 2D boolean grid where each element is either 0 or 1.

    :param grid: A 2D list representing the grid with dimensions m x n, where m is the number of rows and n is the number of columns.
    :return: An integer representing the number of right triangles in the grid.
    """
    def is_triangle(i, j, k):
        return grid[i][k] == 1 and grid[j][i] == 1 and grid[k][j] == 1

    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            for k in range(j + 1, len(grid[0])):
                if is_triangle(i, j, k):
                    count += 1
    return count

